:root {
    --primary-color: #1a1a1a;
    --secondary-color: #ffffff;
    --accent-color: #d4af37;
    --light-bg: #f5f5f5;
    --border-color: #e0e0e0;
    --text-primary: #1a1a1a;
    --text-secondary: #666666;
    --success-color: #2ecc71;
    --danger-color: #e74c3c;
    --transition: all 0.3s ease;
}

/* Reset & Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    color: var(--text-primary);
    background-color: var(--secondary-color);
    line-height: 1.6;
}

a {
    color: var(--text-primary);
    text-decoration: none;
}

button {
    cursor: pointer;
    border: none;
    background: none;
    font-size: inherit;
    font-family: inherit;
}

input,
button {
    outline: 2px solid transparent;
    outline-offset: 2px;
}

input:focus,
button:focus {
    outline: 2px solid var(--accent-color);
    outline-offset: 2px;
}

/* Utility Classes */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

.hidden {
    display: none !important;
}

/* Header */
.header {
    background: var(--secondary-color);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

.header-top {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.5rem 0;
}

.logo h1 {
    font-size: 1.8rem;
    font-weight: 700;
    letter-spacing: -0.5px;
}

.nav-main ul {
    display: flex;
    gap: 2rem;
    list-style: none;
}

.nav-main a {
    font-weight: 500;
    transition: var(--transition);
    position: relative;
    padding-bottom: 0.25rem;
}

.nav-main a:hover {
    color: var(--accent-color);
}

.nav-main a::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--accent-color);
    transition: var(--transition);
}

.nav-main a:hover::after {
    width: 100%;
}

.header-actions {
    display: flex;
    gap: 1.5rem;
    align-items: center;
}

.search-toggle,
.cart-toggle {
    font-size: 1.5rem;
    transition: var(--transition);
    cursor: pointer;
}

.search-toggle:hover,
.cart-toggle:hover {
    transform: scale(1.1);
    color: var(--accent-color);
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -8px;
    background: var(--accent-color);
    color: var(--primary-color);
    border-radius: 50%;
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    font-weight: 700;
}

.cart-toggle {
    position: relative;
}

.search-bar {
    display: flex;
    gap: 0.5rem;
    padding: 1rem 0 0;
    animation: slideDown 0.3s ease;
}

@keyframes slideDown {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.search-input {
    flex: 1;
    padding: 0.75rem 1rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 0.95rem;
}

.search-submit {
    padding: 0.75rem 1.5rem;
    background: var(--primary-color);
    color: var(--secondary-color);
    border-radius: 4px;
    font-weight: 600;
    transition: var(--transition);
}

.search-submit:hover {
    background: var(--accent-color);
    color: var(--primary-color);
}

/* Hero Section */
.hero {
    background: linear-gradient(135deg, #f5f5f5 0%, #ffffff 100%);
    padding: 6rem 2rem;
    text-align: center;
    border-bottom: 1px solid var(--border-color);
}

.hero-content h2 {
    font-size: 3rem;
    margin-bottom: 1rem;
    font-weight: 700;
}

.hero-content p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

/* Buttons */
.btn {
    padding: 0.875rem 2rem;
    border-radius: 4px;
    font-weight: 600;
    transition: var(--transition);
    display: inline-block;
    text-align: center;
}

.btn-primary {
    background: var(--primary-color);
    color: var(--secondary-color);
}

.btn-primary:hover {
    background: var(--accent-color);
