    font-size: 0.85rem;
}

.qty-btn {
    width: 20px;
    height: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--border-color);
    border-radius: 2px;
    cursor: pointer;
    transition: var(--transition);
}

.qty-btn:hover {
    border-color: var(--accent-color);
    color: var(--accent-color);
}

.cart-remove {
    color: var(--danger-color);
    font-size: 0.85rem;
    cursor: pointer;
    transition: var(--transition);
}

.cart-remove:hover {
    text-decoration: underline;
}

.cart-footer {
    padding: 1rem;
    border-top: 2px solid var(--border-color);
}

.cart-total {
    display: flex;
    justify-content: space-between;
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 1rem;
}

/* Overlay for cart modal */
.cart-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    z-index: 999;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s ease;
}

.cart-overlay.active {
    opacity: 1;
    pointer-events: auto;
}

/* Responsive Design */
@media (max-width: 768px) {
    .nav-main {
        display: none;
    }

    .hero-content h2 {
        font-size: 2rem;
    }

    .section-header h2 {
