        grid-template-columns: 1fr;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input,
    .newsletter-form button {
        width: 100%;
    }

    .cart-modal {
        max-width: 100%;
    }
}

@media (max-width: 480px) {
    .header-top {
        padding: 1rem 0;
    }

    .logo h1 {
        font-size: 1.3rem;
    }

    .hero {
        padding: 3rem 1rem;
    }

    .section {
        padding: 2rem 1rem;
    }

    .section-header h2 {
        font-size: 1.5rem;
    }

    .product-card {
        border-radius: 4px;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }
}
