/* Modern Ecommerce Home Page Styles */

:root {
    --primary-color: #1a1a1a;
    --secondary-color: #ffffff;
    --accent-color: #d4af37;
    --light-bg: #f5f5f5;
    --border-color: #e0e0e0;
    --text-primary: #1a1a1a;
    --text-secondary: #666666;
    --success-color: #2ecc71;
    --danger-color: #e74c3c;
    --transition: all 0.3s ease;
}

/* Reset & Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    color: var(--text-primary);
    background-color: var(--secondary-color);
    line-height: 1.6;
}

a {
    color: var(--text-primary);
    text-decoration: none;
}

button {
    cursor: pointer;
    border: none;
    background: none;
    font-size: inherit;
    font-family: inherit;
}

input,
button {
    outline: 2px solid transparent;
    outline-offset: 2px;
}

input:focus,
button:focus {
    outline: 2px solid var(--accent-color);
    outline-offset: 2px;
}

/* Utility Classes */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

.hidden {
    display: none !important;
}

/* Header */
.header {
    background: var(--secondary-color);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

.header-top {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.5rem 0;
}

.logo h1 {
    font-size: 1.8rem;
    font-weight: 700;
    letter-spacing: -0.5px;
}

.nav-main ul {
    display: flex;
    gap: 2rem;
    list-style: none;
}

.nav-main a {
    font-weight: 500;
    transition: var(--transition);
    position: relative;
    padding-bottom: 0.25rem;
}

.nav-main a:hover {
    color: var(--accent-color);
}

.nav-main a::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--accent-color);
    transition: var(--transition);
}

.nav-main a:hover::after {
    width: 100%;
}

.header-actions {
    display: flex;
    gap: 1.5rem;
    align-items: center;
}

.search-toggle,
.cart-toggle {
    font-size: 1.5rem;
    transition: var(--transition);
    cursor: pointer;
}

.search-toggle:hover,
.cart-toggle:hover {
    transform: scale(1.1);
    color: var(--accent-color);
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -8px;
    background: var(--accent-color);
    color: var(--primary-color);
    border-radius: 50%;
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    font-weight: 700;
}

.cart-toggle {
    position: relative;
}

.search-bar {
    display: flex;
    gap: 0.5rem;
    padding: 1rem 0 0;
    animation: slideDown 0.3s ease;
}

@keyframes slideDown {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.search-input {
    flex: 1;
    padding: 0.75rem 1rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 0.95rem;
}

.search-submit {
    padding: 0.75rem 1.5rem;
    background: var(--primary-color);
    color: var(--secondary-color);
    border-radius: 4px;
    font-weight: 600;
    transition: var(--transition);
}

.search-submit:hover {
    background: var(--accent-color);
    color: var(--primary-color);
}

/* Hero Section */
.hero {
    background: linear-gradient(135deg, #f5f5f5 0%, #ffffff 100%);
    padding: 6rem 2rem;
    text-align: center;
    border-bottom: 1px solid var(--border-color);
}

.hero-content h2 {
    font-size: 3rem;
    margin-bottom: 1rem;
    font-weight: 700;
}

.hero-content p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

/* Buttons */
.btn {
    padding: 0.875rem 2rem;
    border-radius: 4px;
    font-weight: 600;
    transition: var(--transition);
    display: inline-block;
    text-align: center;
}

.btn-primary {
    background: var(--primary-color);
    color: var(--secondary-color);
}

.btn-primary:hover {
    background: var(--accent-color);
    color: var(--primary-color);
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(212, 175, 55, 0.2);
}

.btn-full {
    width: 100%;
}

.btn-secondary {
    background: var(--light-bg);
    color: var(--text-primary);
    border: 1px solid var(--border-color);
}

.btn-secondary:hover {
    background: var(--border-color);
}

/* Sections */
.section {
    padding: 4rem 2rem;
}

.section-header {
    text-align: center;
    margin-bottom: 3rem;
}

.section-header h2 {
    font-size: 2.5rem;
    margin-bottom: 0.5rem;
    font-weight: 700;
}

.section-subtitle {
    color: var(--text-secondary);
    font-size: 1.1rem;
}

/* Products Grid */
.products-grid,
.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 2rem;
}

.product-card {
    background: var(--secondary-color);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
    transform: translateY(-4px);
}

.product-image {
    width: 100%;
    height: 280px;
    background: linear-gradient(135deg, #f0f0f0 0%, #e0e0e0 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.product-info {
    padding: 1.5rem;
    flex: 1;
    display: flex;
    flex-direction: column;
}

.product-category {
    font-size: 0.75rem;
    color: var(--accent-color);
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 0.5rem;
}

.product-name {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
    line-height: 1.4;
}

.product-description {
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-bottom: 1rem;
    flex: 1;
}

.product-rating {
    display: flex;
    gap: 0.25rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.product-price {
    font-size: 1.3rem;
    font-weight: 700;
    margin-bottom: 1rem;
}

.product-price.sale {
    color: var(--danger-color);
}

.price-original {
    text-decoration: line-through;
    color: var(--text-secondary);
    font-size: 1rem;
    font-weight: 400;
    margin-right: 0.5rem;
}

.discount-badge {
    display: inline-block;
    background: var(--danger-color);
    color: white;
    padding: 0.25rem 0.75rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
}

.product-actions {
    display: flex;
    gap: 0.75rem;
}

.add-to-cart {
    flex: 1;
    padding: 0.75rem;
    background: var(--primary-color);
    color: var(--secondary-color);
    border-radius: 4px;
    font-weight: 600;
    transition: var(--transition);
}

.add-to-cart:hover {
    background: var(--accent-color);
    color: var(--primary-color);
}

.wishlist-btn {
    padding: 0.75rem 1rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    transition: var(--transition);
}

.wishlist-btn:hover {
    border-color: var(--accent-color);
    color: var(--accent-color);
}

/* Deals Section */
.deals {
    background: var(--light-bg);
}

.deal-card {
    background: var(--secondary-color);
    border-radius: 8px;
    overflow: hidden;
    display: grid;
    grid-template-columns: 1fr 1fr;
    transition: var(--transition);
}

.deal-card:hover {
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
}

.deal-image {
    background: linear-gradient(135deg, #f0f0f0 0%, #e0e0e0 100%);
    height: 220px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 4rem;
}

.deal-info {
    padding: 2rem;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.deal-category {
    font-size: 0.75rem;
    color: var(--accent-color);
    font-weight: 700;
    text-transform: uppercase;
    margin-bottom: 0.5rem;
}

.deal-title {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
}

.deal-description {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    font-size: 0.95rem;
}

.deal-price {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
}

.deal-countdown {
    display: flex;
    gap: 1rem;
    margin-bottom: 1.5rem;
    font-size: 0.85rem;
}

.time-unit {
    text-align: center;
}

.time-value {
    display: block;
    font-size: 1.2rem;
    font-weight: 700;
    color: var(--accent-color);
}

/* Editorial Section */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 2rem;
}

.article-card {
    background: var(--secondary-color);
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.article-card:hover {
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
    transform: translateY(-4px);
}

.article-image {
    width: 100%;
    height: 200px;
    background: linear-gradient(135deg, #f0f0f0 0%, #e0e0e0 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
}

.article-content {
    padding: 1.5rem;
    flex: 1;
    display: flex;
    flex-direction: column;
}

.article-date {
    font-size: 0.75rem;
    color: var(--text-secondary);
    margin-bottom: 0.75rem;
    text-transform: uppercase;
}

.article-title {
    font-size: 1.3rem;
    font-weight: 700;
    margin-bottom: 0.75rem;
    line-height: 1.4;
}

.article-excerpt {
    color: var(--text-secondary);
    margin-bottom: 1rem;
    flex: 1;
    font-size: 0.95rem;
}

.article-link {
    color: var(--accent-color);
    font-weight: 600;
    transition: var(--transition);
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
}

.article-link:hover {
    gap: 1rem;
}

/* Newsletter Section */
.newsletter {
    background: var(--primary-color);
    color: var(--secondary-color);
    padding: 4rem 2rem;
    text-align: center;
}

.newsletter-content h3 {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.newsletter-content p {
    margin-bottom: 2rem;
    font-size: 1.05rem;
    opacity: 0.9;
}

.newsletter-form {
    display: flex;
    gap: 0.75rem;
    max-width: 500px;
    margin: 0 auto;
    flex-wrap: wrap;
    justify-content: center;
}

.newsletter-form input {
    flex: 1;
    min-width: 200px;
    padding: 0.875rem 1rem;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
}

.newsletter-form button {
    padding: 0.875rem 2rem;
    background: var(--accent-color);
    color: var(--primary-color);
    border-radius: 4px;
    font-weight: 600;
    transition: var(--transition);
}

.newsletter-form button:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(212, 175, 55, 0.3);
}

/* Footer */
.footer {
    background: #2a2a2a;
    color: #ffffff;
    padding: 3rem 2rem 1rem;
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer-col h4 {
    font-size: 1rem;
    margin-bottom: 1rem;
    font-weight: 700;
}

.footer-col ul {
    list-style: none;
}

.footer-col li {
    margin-bottom: 0.75rem;
}

.footer-col a {
    color: #cccccc;
    transition: var(--transition);
    font-size: 0.95rem;
}

.footer-col a:hover {
    color: var(--accent-color);
}

.social-links {
    display: flex;
    gap: 1rem;
}

.social-links a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border: 1px solid #555555;
    border-radius: 50%;
    transition: var(--transition);
}

.social-links a:hover {
    border-color: var(--accent-color);
    color: var(--accent-color);
}

.footer-bottom {
    text-align: center;
    padding-top: 2rem;
    border-top: 1px solid #444444;
    color: #999999;
    font-size: 0.9rem;
}

/* Shopping Cart Modal */
.cart-modal {
    position: fixed;
    top: 0;
    right: -400px;
    width: 100%;
    max-width: 400px;
    height: 100vh;
    background: var(--secondary-color);
    box-shadow: -2px 0 8px rgba(0, 0, 0, 0.15);
    z-index: 1000;
    transition: right 0.3s ease;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.cart-modal:not(.hidden) {
    right: 0;
}

.cart-content {
    display: flex;
    flex-direction: column;
    height: 100%;
    padding-bottom: 1rem;
}

.cart-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.5rem;
    border-bottom: 1px solid var(--border-color);
}

.cart-header h3 {
    font-size: 1.3rem;
}

.cart-close {
    font-size: 1.5rem;
    cursor: pointer;
    transition: var(--transition);
    padding: 0.5rem;
}

.cart-close:hover {
    color: var(--accent-color);
}

.cart-items {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
}

.empty-message {
    text-align: center;
