        excerpt: 'Master the techniques to elevate any outfit with the right accessories.',
        date: 'April 25, 2026',
        emoji: '✨'
    },
];

// State
let cart = [];

// DOM Elements
const searchToggle = document.querySelector('.search-toggle');
const searchBar = document.getElementById('search-bar');
const cartToggle = document.querySelector('.cart-toggle');
const cartModal = document.getElementById('cart-modal');
const cartClose = document.querySelector('.cart-close');
const productsGrid = document.querySelector('.products-grid');
const dealsGrid = document.querySelector('.deals-grid');
const editorialGrid = document.querySelector('.editorial-grid');
const cartCount = document.querySelector('.cart-count');
const cartItemsContainer = document.getElementById('cart-items');
const cartTotal = document.getElementById('cart-total');
const newsletterForm = document.querySelector('.newsletter-form');

// Initialize
document.addEventListener('DOMContentLoaded', () => {
    renderProducts();
    renderDeals();
    renderEditorial();
    setupEventListeners();
});

// Event Listeners
function setupEventListeners() {
    searchToggle.addEventListener('click', toggleSearch);
    cartToggle.addEventListener('click', toggleCart);
    cartClose.addEventListener('click', closeCart);
    newsletterForm.addEventListener('submit', handleNewsletterSubmit);

    // Close cart when clicking outside
    document.addEventListener('click', (e) => {
        if (!cartModal.contains(e.target) && e.target !== cartToggle && !cartToggle.contains(e.target)) {
            if (!cartModal.classList.contains('hidden')) {
                closeCart();
            }
        }
    });

    // Keyboard shortcuts
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            closeCart();
            closeSearch();
        }
    });
}

// Search functionality
function toggleSearch() {
    searchBar.classList.toggle('hidden');
    if (!searchBar.classList.contains('hidden')) {
        searchBar.querySelector('.search-input').focus();
        searchToggle.setAttribute('aria-expanded', 'true');
    } else {
        searchToggle.setAttribute('aria-expanded', 'false');
    }
}

function closeSearch() {
    searchBar.classList.add('hidden');
    searchToggle.setAttribute('aria-expanded', 'false');
}

// Cart functionality
function toggleCart() {
    cartModal.classList.toggle('hidden');
}

function closeCart() {
    cartModal.classList.add('hidden');
}

function addToCart(productId) {
    const product = products.find(p => p.id === productId);
    const existingItem = cart.find(item => item.id === productId);

    if (existingItem) {
        existingItem.quantity += 1;
    } else {
        cart.push({ ...product, quantity: 1 });
    }

    updateCart();
    showNotification(`${product.name} added to cart!`);
}

function removeFromCart(productId) {
    cart = cart.filter(item => item.id !== productId);
    updateCart();
}

function updateItemQuantity(productId, change) {
    const item = cart.find(item => item.id === productId);
    if (item) {
        item.quantity += change;
        if (item.quantity <= 0) {
            removeFromCart(productId);
        } else {
            updateCart();
        }
    }
}

function updateCart() {
    updateCartCount();
    renderCartItems();
    updateCartTotal();
}

function updateCartCount() {
    const count = cart.reduce((total, item) => total + item.quantity, 0);
    cartCount.textContent = count;
}

function renderCartItems() {
    if (cart.length === 0) {
        cartItemsContainer.innerHTML = '<p class="empty-message">Your cart is empty</p>';
        return;
    }

    cartItemsContainer.innerHTML = cart.map(item => `
        <div class="cart-item">
            <div class="cart-item-image">${item.emoji}</div>
            <div class="cart-item-info">
                <div class="cart-item-name">${item.name}</div>
                <div class="cart-item-price">$${item.price.toFixed(2)}</div>
                <div class="cart-item-qty">
                    <button class="qty-btn" aria-label="Decrease quantity" onclick="updateItemQuantity(${item.id}, -1)">−</button>
                    <span>${item.quantity}</span>
                    <button class="qty-btn" aria-label="Increase quantity" onclick="updateItemQuantity(${item.id}, 1)">+</button>
                    <span class="cart-remove" onclick="removeFromCart(${item.id})" role="button" tabindex="0">Remove</span>
                </div>
            </div>
        </div>
    `).join('');
}

function updateCartTotal() {
    const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    cartTotal.textContent = `$${total.toFixed(2)}`;
}

// Render functions
function renderProducts() {
    productsGrid.innerHTML = products.map(product => `
        <div class="product-card">
            <div class="product-image">${product.emoji}</div>
            <div class="product-info">
                <span class="product-category">${product.category}</span>
                <h3 class="product-name">${product.name}</h3>
                <p class="product-description">Premium quality product designed for modern living</p>
                <div class="product-rating" aria-label="${product.rating} out of 5 stars">
