                <div class="product-price">$${product.price.toFixed(2)}</div>
                <div class="product-actions">
                    <button class="add-to-cart" onclick="addToCart(${product.id})" aria-label="Add ${product.name} to cart">
                        Add to Cart
                    </button>
                    <button class="wishlist-btn" aria-label="Add to wishlist" title="Add to wishlist">♡</button>
                </div>
            </div>
        </div>
    `).join('');
}

function renderDeals() {
    dealsGrid.innerHTML = deals.map(deal => `
        <div class="deal-card">
            <div class="deal-image">${deal.emoji}</div>
            <div class="deal-info">
                <span class="deal-category">Limited Time</span>
